mapper.select:
SELECT p.product_id AS productId, p.shop_id AS shopId, s.shop_name AS shopName, p.category_id AS categoryId, p.product_name AS productName, p.description AS description, p.image_url AS imageUrl, p.price AS price, p.status AS status, p.stock AS stock, p.sold_count AS soldCount, p.create_time AS createTime FROM mobi_shop_product p LEFT JOIN mobi_shop s ON s.id = p.shop_id
AND p.shop_id = #{query.shopId}
AND p.product_name LIKE CONCAT('%', #{query.productName}, '%')
AND p.status = #{query.status}
ORDER BY p.product_id DESC
